using Fleet.Api.Models; using Microsoft.EntityFrameworkCore;
namespace Fleet.Api.Data;
public sealed class FleetDbContext(DbContextOptions<FleetDbContext> options):DbContext(options){public DbSet<User> Users=>Set<User>();public DbSet<Vehicle> Vehicles=>Set<Vehicle>();public DbSet<Driver> Drivers=>Set<Driver>();public DbSet<Assignment> Assignments=>Set<Assignment>();public DbSet<MaintenanceRecord> MaintenanceRecords=>Set<MaintenanceRecord>();protected override void OnModelCreating(ModelBuilder b){b.Entity<User>().HasIndex(x=>x.Username).IsUnique();b.Entity<User>().HasIndex(x=>x.DriverId).IsUnique();b.Entity<Vehicle>().HasIndex(x=>x.PlateNumber).IsUnique();b.Entity<Driver>().HasIndex(x=>x.LicenseNumber).IsUnique();b.Entity<MaintenanceRecord>().Property(x=>x.Cost).HasPrecision(14,2);}}
